  if (cached && (Date.now() - cached.at) < 10000) return cached.cfg;
  const base = env.get('RADIO_PROXY_URL') || 'http://radio-proxy:8091';
  const res = await fetch(base + '/config');
  if (!res.ok) throw new Error('fetchCfg ' + res.status);
  const cfg = await res.json();
  flow.set('cfgCache', { at: Date.now(), cfg });
  return cfg;
}
function resolveTarget(cfg, target) {
  if (!target) throw new Error('Missing target');
  if (target.startsWith('speaker:')) {
    const id = target.slice(8); const speaker = cfg.speakers[id];
    if (!speaker) throw new Error('Unknown speaker ' + id);
    return { type: 'speaker', id, speaker, zoneName: '' };
  }
  if (target.startsWith('zone:')) {
    const id = target.slice(5); const zone = cfg.zones[id];
    if (!zone) throw new Error('Unknown zone ' + id);
    const master = cfg.speakers[zone.master];
    if (!master) throw new Error('Unknown zone master ' + zone.master);
    return { type: 'zone', id, zone, speaker: master, speakerId: zone.master, zoneName: zone.name || id };
  }
  throw new Error('Target must start with speaker: or zone:');
}
function buildStorePresetXml(presetId, station, piIp, proxyPort) {
  const location = 'http://' + piIp + ':' + proxyPort + station.path;
  return [
    '<preset id="' + presetId + '">',
    '  <ContentItem source="LOCAL_INTERNET_RADIO" type="stationurl" location="' + location + '">',
    '    <itemName>' + (station.name || '') + '</itemName>',
    '  </ContentItem>',
    '</preset>',
  ].join('\n');
}
(async () => {
  try {
    const cfg = await fetchCfg();
    const body = msg.payload || {};
    const target = resolveTarget(cfg, body.target);
    const speaker = target.speaker;
    const piIp = env.get('PI_IP') || '10.0.0.241';
    const proxyPort = env.get('PROXY_PORT') || 8091;
    const results = [];
    for (const presetKey of ['PRESET_1','PRESET_2','PRESET_3','PRESET_4','PRESET_5','PRESET_6']) {
      const stationId = (cfg.presets || {})[presetKey];
      if (!stationId) {
        results.push({ presetKey, ok: false, error: 'unset' });
        continue;
      }
      const station = (cfg.stations || {})[stationId];
      if (!station) {
        results.push({ presetKey, ok: false, error: 'missing station ' + stationId });
        continue;
      }
      const presetId = presetKey.replace('PRESET_', '');
      const xml = buildStorePresetXml(presetId, station, piIp, proxyPort);
      const res = await fetch('http://' + speaker.ip + ':8090/storePreset', {
        method: 'POST',
        headers: { 'Content-Type': 'application/xml' },
        body: xml,
      });
      const text = await res.text();
      if (!res.ok) {
        results.push({ presetKey, ok: false, stationId, error: 'storePreset ' + res.status + ': ' + text });
      } else {
        results.push({ presetKey, ok: true, stationId, result: text });
      }
      await new Promise(r => setTimeout(r, 200));
    }
    msg.payload = { ok: results.every(r => r.ok), target: body.target, speaker: speaker.name || speaker.ip, results };
    node.send(msg);
  } catch (e) {
    msg.statusCode = 500; msg.payload = { ok: false, error: e.message || String(e) }; node.send(msg);
  }
})();
return null;
